SELECT supplier_id, STDDEV_SAMP(stock_qty) AS stock_qty_stddev, SORT_ARRAY(COLLECT_SET(category)) AS category_list, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, COUNT(*) FILTER (WHERE category = 'Electronics') AS electronics_rows, COUNT_IF(brand = 'Globex') AS globex_events FROM products GROUP BY supplier_id HAVING COUNT_IF(brand = 'Globex') > 1 ORDER BY supplier_id DESC NULLS LAST
